<script>
    // 1. Manejador de Modo Claro / Modo Oscuro
    const themeBtn = document.getElementById('theme-toggle-btn');
    const themeIcon = document.getElementById('theme-icon');
    const themeText = document.getElementById('theme-text');
    const htmlEl = document.documentElement;

    function applyTheme(isDark) {
      if (isDark) {
        htmlEl.classList.add('dark');
        themeIcon.textContent = 'light_mode';
        themeText.textContent = 'Modo Día';
      } else {
        htmlEl.classList.remove('dark');
        themeIcon.textContent = 'dark_mode';
        themeText.textContent = 'Modo Noche';
      }
    }

    // Comprobar preferencia previa o inicial
    let isDarkMode = htmlEl.classList.contains('dark') || false;
    applyTheme(isDarkMode);

    themeBtn.addEventListener('click', () => {
      isDarkMode = !isDarkMode;
      applyTheme(isDarkMode);
    });

    // 2. Microinteracción para botones "Agregar +"
    
const toast = document.getElementById('cart-toast');

const parametros = new URLSearchParams(window.location.search);

if (toast && parametros.get('agregado') === '1') {
    toast.classList.remove('translate-y-[-150%]', 'opacity-0');
    toast.classList.add('translate-y-0', 'opacity-100');

    setTimeout(() => {
        toast.classList.remove('translate-y-0', 'opacity-100');
        toast.classList.add('translate-y-[-150%]', 'opacity-0');
    }, 2200);

    window.history.replaceState(
        {},
        document.title,
        window.location.pathname
    );
}

  </script>
